#!/bin/sh
# Starts sshd (SFTP only, chrooted user "dcdash" in group bind) and named.
# The SSH host key and dcdash's public key are generated by
# scripts/integration-test.sh and mounted at /keys.
set -eu

adduser -D -H -G bind -s /sbin/nologin dcdash
# adduser locks the account ("!"); sshd refuses locked accounts.
sed -i 's/^dcdash:!/dcdash:*/' /etc/shadow

# The chroot must belong to root; the zone directory is shared with named
# (setgid group bind, so named can read and write the files and journals).
mkdir -p /srv/sftp/zones /etc/ssh/authorized
chown root:root /srv/sftp
chmod 755 /srv/sftp
chown bind:bind /srv/sftp/zones
chmod 2775 /srv/sftp/zones

cp /keys/host_ed25519 /etc/ssh/ssh_host_ed25519_key
chmod 600 /etc/ssh/ssh_host_ed25519_key
cp /keys/client_ed25519.pub /etc/ssh/authorized/dcdash
chmod 644 /etc/ssh/authorized/dcdash

cat > /etc/ssh/sshd_config <<'CONF'
HostKey /etc/ssh/ssh_host_ed25519_key
AuthorizedKeysFile /etc/ssh/authorized/%u
PasswordAuthentication no
KbdInteractiveAuthentication no
PermitRootLogin no
Subsystem sftp internal-sftp
Match User dcdash
  ChrootDirectory /srv/sftp
  ForceCommand internal-sftp -u 0002
  AllowTcpForwarding no
  X11Forwarding no
CONF
/usr/sbin/sshd -e

cp /config/catalog.zone /config/static.zone /var/lib/bind/
chown bind:bind /var/lib/bind/catalog.zone /var/lib/bind/static.zone
exec /usr/sbin/named -u bind -g -c /config/named.conf
